// The CRM sends { event, occurred_at, data } — data is the deal.
const deal = $json.body.data;

const amount = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: deal.currency || 'USD',
}).format(deal.value ?? 0);

const contact = deal.contact
  ? `${deal.contact.first_name} ${deal.contact.last_name ?? ''}`.trim()
  : 'n/a';

return {
  json: {
    subject: `🎉 Deal won: ${deal.title} (${amount})`,
    text: [
      `Deal: ${deal.title}`,
      `Value: ${amount}`,
      `Company: ${deal.company?.name ?? 'n/a'}`,
      `Contact: ${contact}`,
      `Owner: ${deal.owner?.full_name ?? 'n/a'}`,
    ].join('\n'),
  },
};
